CustomField.formula:
IF(
/*If Account is Country Parent, stores Data_Centre_Owner__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Data_Centre_Owner__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's Data_Centre_Owner__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Data_Centre_Owner__c,Data_Centre_Owner__c))
